"""${{ values.name }} — generated by the chatbot blueprint v6.1.0."""
import os

from platform_sdk import Context, Gateway

ALIAS = os.environ.get("SERVICE_ALIAS", "${{ values.alias }}")
gateway = Gateway(ctx=Context(tenant="${{ values.tenant }}", feature="chatbot"))


def reply(history: list[dict], user_text: str) -> str:
    msgs = history + [{"role": "user", "content": user_text}]
    return gateway.chat(msgs, alias=ALIAS).text


def eval_answer(question: str):
    return reply([], question), []
